module tb_TopModule;
    logic [1:0] A;
    logic [1:0] B;
    logic       z;

    TopModule dut (
        .A(A),
        .B(B),
        .z(z)
    );

    initial begin
        integer i, j;
        logic expected;

        for (i = 0; i < 4; i = i + 1) begin
            for (j = 0; j < 4; j = j + 1) begin
                A = i[1:0];
                B = j[1:0];
                #10;
                expected = (A == B);
                if (z !== expected) begin
                    $display("SELFTEST FAIL: A=%b, B=%b, got z=%b, expected=%b", A, B, z, expected);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
